balances = Hash(default_value=0)

metadata = Hash()

@construct
def seed():
    balances[ctx.caller] = 1000000000

    metadata["token_name"] = "taurus"
    metadata["token_symbol"] = "TRS"
    metadata["token_logo_base64_png"] = ""
    metadata["operator"] = "9efd0891225cbc0044645009524bb0320ca606068651619541a6c5d8d0dd8171"

@export
def change_metadata(key: str, value: Any):
    assert ctx.caller == metadata["operator"], "Only operator can set metadata!"
    metadata[key] = value

@export
def transfer(amount: float, to: str):
    assert amount > 0, "Cannot send negative balances!"
    assert balances[ctx.caller] >= amount, "Not enough coins to send!"

    balances[ctx.caller] -= amount
    balances[to] += amount

@export
def approve(amount: float, to: str):
    assert amount > 0, "Cannot send negative balances!"
    balances[ctx.caller, to] += amount

@export
def transfer_from(amount: float, to: str, main_account: str):
    assert amount > 0, "Cannot send negative balances!"
    assert balances[main_account, ctx.caller] >= amount, "Not enough coins approved to send! You have {} and are trying to spend {}".format(balances[main_account, ctx.caller], amount)
    assert balances[main_account] >= amount, "Not enough coins to send!"

    balances[main_account, ctx.caller] -= amount
    balances[main_account] -= amount
    balances[to] += amount

@export
def mint(amount: float):
    assert ctx.caller == metadata["operator"], "Only operator can mint!"
    assert amount > 0, "Cannot mint negative amount!"
    balances[ctx.caller] += amount


@export
def burn(amount: float):
    assert amount > 0, "Cannot burn negative amount!"
    assert balances[ctx.caller] >= amount, "Not enough coins to burn!"
    balances["BURNED"] += amount
    balances[ctx.caller] -= amount
